// 通用确认框 (挂在应用根节点, 与未保存确认框并列)。
//
// 需要"先问一句"的地方都走 `confirm.ts` 的 `requestConfirm`, 由这里统一渲染 ——
// 样式与场景浏览器里的删除确认是同一个 `ConfirmDialog`。

import { useAppStore } from '../state/store';
import { pendingConfirm, resolveConfirm } from '../confirm';
import { ConfirmDialog } from './SceneFileDialogs';

export function AppConfirmDialog() {
  const open = useAppStore((s) => s.confirmDialog);
  const request = pendingConfirm();
  if (!open || !request) return null;

  return (
    <ConfirmDialog
      title={request.title}
      message={request.description}
      confirmLabel={request.confirmLabel}
      danger={request.danger}
      info={request.info}
      onClose={() => resolveConfirm(false)}
      onConfirm={async () => {
        resolveConfirm(true);
        return null;
      }}
    />
  );
}
